import pandas as pd
import glob
import os

def merge_geant4_data(directory_path, output_filename):
    # Search for all files generated by Geant4 threads in the specified directory
    file_pattern = os.path.join(directory_path, "simulation_baseline_nt_Hits_t*.csv")
    files = glob.glob(file_pattern)
    
    if not files:
        print(f"No files found at path: {file_pattern}")
        return
        
    column_names = [
        'Ekin_MeV', 
        'Total_Edep_MeV', 
        'Electron_Edep_MeV', 
        'Proton_Edep_MeV', 
        'Secondary_Edep_MeV'
    ]
    
    df = pd.concat(
        (pd.read_csv(f, comment='#', names=column_names) for f in files), 
        ignore_index=True
    )
    
    print(f"Success! Merged {len(files)} files.")
    print(f"Total events recorded: {len(df)}")
    os.makedirs(os.path.dirname(output_filename), exist_ok=True)
    
    # Save the merged file without the pandas index
    df.to_csv(output_filename, index=False)
    print(f"Data successfully saved to: {output_filename}")
    
    return df


